/// <summary>
/// Code added by TCS
/// Service class, Business logic to update vendor address : Legal entity lookup 
/// </summary>
class MET_VendorAddsUpdateService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// Set parameter and run class <c> LocationRecordsProcessor </c> to set functional location records
    /// </summary>
    /// <param name = "LocationRecordsContract">LocationRecordsContract</param>
    public void LocationRecordsService(MET_VendorAddsUpdateContract _vendorAddsUpdateContract)
    {
        List dataEntity = new List(Types::String);
        ListEnumerator              enumerator;
        VendTable                   VendTable;
        DirPartyTable               dirPartyTable;
        DirPartyLocation            dirPartyLocation;
        logisticsLocation           logisticsLocation;
        LogisticsLocationRole       logisticsLocationRole;
        DirPartyLocationRole        dirPartyLocationRole;
        VendPaymMode                paymMethod;
        LogisticsLocationRoletype   purpose;
        int                         i;



        purpose    = _vendorAddsUpdateContract.parmlogisticsLocationRoleType();
        paymMethod = _vendorAddsUpdateContract.parmPaymMode();
        dataEntity = _vendorAddsUpdateContract.parmSelectedLegalEntities();
        // you can write business Logic here
        enumerator = dataEntity.getEnumerator();
        enumerator.reset();
        while(enumerator.moveNext())
        {
            changecompany(enumerator.current())
            {
                i = 0;
                ttsbegin;
                while select vendTable
                join dirPartyTable
                where vendTable.Party == dirPartyTable.RecId
                join dirPartyLocation
                where dirPartyLocation.Party == dirPartyTable.RecId
                && dirPartyLocation.IsPrimary != true // To get primary address is not ticked
                join logisticsLocation
                where logisticsLocation.RecId == dirPartyLocation.Location
                join dirPartyLocationRole
                where dirPartyLocationRole.PartyLocation == dirPartyLocation.RecId
                join logisticsLocationRole
                where logisticsLocationRole.RecId == dirPartyLocationRole.LocationRole
                && logisticsLocationRole.Type == purpose && VendTable.PaymMode == paymMethod
                {
                    i++;
                    dirPartyLocation.selectForUpdate(true);
                    dirPartyLocation.IsPrimary = NoYes::Yes;
                    dirPartyLocation.update();
                    
                }
                ttscommit;
                Info(strFmt("@MET:ForRecordCount",enumerator.current(),i));
            }
        }
    }
